/* JS malloc */

/* allow iteration among the allocated blocks. Currently not used. May
   be used to suppress the memory overhead of JSGCObjectHeader */
//#define JS_MALLOC_USE_ITER

// C documentation
//
//	/* 8 byte header */
//	/* Notes:
//	   - the header is necessary at least to recover a pointer to
//	     JSMallocArena because we don't want to enforce a page
//	     alignment on the system malloc().
//	   - could store the block offset instead of (block_idx,
//	   block_size_idx), but it would require a division to recover the block
//	   index.
//	*/
type TJSMallocBlockHeader = struct {
	F__ccgo_align [0]uint64
	Fu            struct {
		Ffree_next [0]Tuint16_t
		Fblock_idx Tuint16_t
	}
	Fblock_size_idx Tuint8_t
	F__ccgo3        uint8
	Fref_count      int32
}

type TJSMallocLargeBlockHeader = struct {
	Fheader TJSMallocBlockHeader
}

type TJSMallocArena = struct {
	Ffree_link        Tlist_head
	Flink             Tlist_head
	Fblock_size_idx   Tuint8_t
	Fn_used_blocks    Tuint16_t
	Fn_blocks         Tuint16_t
	Ffirst_free_block Tuint16_t
}

type TJSMallocContext = struct {
	Farena_list      [31]Tlist_head
	Ffree_arena_list [31]Tlist_head
	Fzero_size_block [8]Tuint8_t
	Fmf              TJSMallocFunctions
	Fmalloc_state    TJSMallocState
}

